package com.fluxisai.task;
import java.util.UUID; import com.fluxisai.audit.AuditEventService; import com.fluxisai.common.error.ResourceNotFoundException; import com.fluxisai.common.security.CurrentUser; import com.fluxisai.common.web.PageResponse; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class TaskService {private final TaskRepository tasks;private final AuditEventService audit;private final CurrentUser currentUser;public TaskService(TaskRepository t,AuditEventService a,CurrentUser u){tasks=t;audit=a;currentUser=u;} @Transactional public TaskResponse create(TaskRequest r){var t=tasks.save(new Task(currentUser.id(),clean(r.title()),optional(r.description()),r.dueDate(),r.priority(),r.status(),r.origin(),r.relatedEntityType(),r.relatedEntityId()));var saved=tasks.save(t);audit.record("TASK","TASK",saved.getId(),"CREATED",details(saved));return TaskResponse.from(saved);} @Transactional(readOnly=true) public TaskResponse get(UUID id){return TaskResponse.from(find(id));} @Transactional(readOnly=true) public PageResponse<TaskResponse> list(Pageable p){return PageResponse.from(tasks.findAllByUserId(currentUser.id(),p).map(TaskResponse::from));} @Transactional public TaskResponse update(UUID id,TaskRequest r){var t=find(id);t.update(clean(r.title()),optional(r.description()),r.dueDate(),r.priority(),r.status(),r.origin(),r.relatedEntityType(),r.relatedEntityId());var saved=tasks.save(t);audit.record("TASK","TASK",id,"UPDATED",details(saved));return TaskResponse.from(saved);} @Transactional public void delete(UUID id){var t=find(id);tasks.delete(t);audit.record("TASK","TASK",id,"DELETED",details(t));} private Task find(UUID id){return tasks.findByIdAndUserId(id,currentUser.id()).orElseThrow(()->new ResourceNotFoundException("No se encontró la tarea"));} private static String clean(String v){return v.trim();} private static String optional(String v){if(v==null)return null;var x=v.trim();return x.isEmpty()?null:x;} private static String details(Task t){return "{\"title\":\""+t.getTitle().replace("\"","'")+"\",\"status\":\""+t.getStatus()+"\"}";}}
